import assert from 'node:assert/strict';
import {Engine, memoryStore} from '../static/engine.mjs';
const store = memoryStore(), e = new Engine({store,base:'https://fixture.example',push:{supported:()=>true}});
let calls = 0, changes = 0;
e.call = async (_method,path) => { calls++; assert.equal(path,'/v1/notify'); return {push_key:'fixture-key'}; };
e.listen(() => changes++);
let view = await e.notifyView();
assert.equal(calls,0); assert.equal(view.available,false); assert.match(view.reason,/not been checked/);
e.featureList = ['notify1'];
view = await e.notifyView();
assert.equal(calls,0); assert.equal(view.available,false); assert.match(view.reason,/not been checked/);
await e.notifyInfo();
assert.equal(calls,1); assert.equal(changes,1,'verified offer refreshes existing listeners');
view = await e.notifyView();
assert.equal(calls,1); assert.equal(view.available,true); assert.equal(view.reason,'');
e.featureList = null;
assert.equal((await e.notifyView()).available,true,'same-workspace cached offer remains useful offline');
await store.write([{s:'kv',k:'notify',v:{enabled:true,rev:2,synced:1,mutes:[],allowed:[],chat_mutes:1}}]);
view = await e.notifyView(); assert.equal(view.enabled,true); assert.equal(view.pending,true);
e.featureList = [];
view = await e.notifyView(); assert.equal(view.available,false); assert.match(view.reason,/does not send/);
assert.equal(await e.notifyInfo(),null); assert.equal(calls,1,'action capability semantics stay enforced');
e.featureList = ['notify1']; e.push = {supported:()=>false};
view = await e.notifyView(); assert.equal(view.available,false); assert.match(view.reason,/browser cannot/);
assert.equal(calls,1);
console.log('cached notification presentation and verified capability refresh PASS');
